import sys
from itertools import permutations

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
frm = data[2:2 + m]
to = data[2 + m:2 + 2 * m]
adj = [[] for _ in range(n + 1)]
for i in range(m):
    a = int(frm[i])
    b = int(to[i])
    adj[a].append(b)
    adj[b].append(a)
parent = {1: 0}
stack = [1]
while stack:
    u = stack.pop()
    for v in adj[u]:
        if v not in parent:
            parent[v] = u
            stack.append(v)
count = 0
for perm in permutations(range(2, n + 1)):
    colored = {1}
    good = True
    for v in perm:
        if parent[v] not in colored:
            good = False
            break
        colored.add(v)
    if good:
        count += 1
print(count % (10**9 + 7))

